import type { CustomBlockInitializationError } from "@notionhq/custom-blocks-protocol/messages/init.js"
import { type ReactNode, useEffect, useLayoutEffect, useState } from "react"
import { customBlockHost } from "../bridge/sandboxClient.js"
import { NotInIframeError } from "../init.js"
import { DebugMessageLog } from "./DebugMessageLog.js"
import { seedStandalonePreviewState } from "./standalonePreview.js"
import { useCustomBlockAutoResize } from "./useCustomBlockAutoResize.js"
import { useCustomBlockInit } from "./useCustomBlockInit.js"
import { useCustomBlockHost } from "./useHostState.js"
import "./NotionCustomBlock.css"

/**
 * Props accepted by {@link NotionCustomBlock}.
 */
export type NotionCustomBlockProps = {
	children: ReactNode
	/**
	 * Rendered while the SDK ↔ host handshake is in progress. Defaults to
	 * `null` (nothing).
	 */
	fallback?: ReactNode
	/**
	 * Rendered when the handshake fails. Either a node, or a function that
	 * receives the `Error`. When omitted, a friendly default error card is
	 * rendered with developer details — replace it for production templates.
	 */
	errorFallback?: ReactNode | ((error: Error) => ReactNode)
	/**
	 * Whether to post resize messages after initialization and dynamically resize the block.
	 *
	 * @deprecated TODO(custom-blocks): Remove this prop when bumping the SDK version to 0.2.0.
	 *
	 * @default true
	 */
	autoResize?: boolean
}

/**
 * Top-level wrapper that runs the SDK ↔ host handshake and gates `children`
 * until it resolves.
 *
 * Templates that prefer not to write a `Root` gating component (or top-level
 * `await`) can mount their app entirely inside this provider:
 *
 * ```tsx
 * ReactDOM.createRoot(root).render(
 *   <NotionCustomBlock>
 *     <App />
 *   </NotionCustomBlock>,
 * )
 * ```
 *
 * Inside `children`, every SDK hook is guaranteed to return a populated
 * value. Outside the provider (or during the loading window), they throw.
 */
export function NotionCustomBlock({
	children,
	fallback = null,
	errorFallback,
	autoResize = true,
}: NotionCustomBlockProps) {
	const init = useCustomBlockInit()
	useCustomBlockAutoResize({ enabled: init.isLoaded && autoResize })
	// True if the block has no host (i.e. it's running in standalone preview).
	const isStandalone = init.error instanceof NotInIframeError
	const host = useCustomBlockHost()
	const [debugOpen, setDebugOpen] = useState(false)

	useEffect(() => {
		const onKeyDown = (e: KeyboardEvent) => {
			if (e.key === "\\") {
				setDebugOpen(prev => !prev)
			}
		}
		window.addEventListener("keydown", onKeyDown)
		return () => window.removeEventListener("keydown", onKeyDown)
	}, [])

	useEffect(() => {
		if (!isStandalone) {
			return
		}
		console.warn(`[custom-blocks-sdk] ${init.error?.message}`)
		seedStandalonePreviewState()
	}, [isStandalone, init.error])

	useLayoutEffect(() => {
		if (!init.isLoaded || isStandalone) {
			return
		}
		// Send `initResult` *after* React renders the block so the SDK can report its rendered
		// height to the host as part of the `initResult` message.
		customBlockHost.completeInitialization()
	}, [init.isLoaded, isStandalone])

	if (debugOpen) {
		return <DebugMessageLog />
	}
	if (init.error && !isStandalone) {
		if (errorFallback === undefined) {
			return <DefaultInitErrorFallback error={init.error} />
		}
		return (
			<>
				{typeof errorFallback === "function"
					? errorFallback(init.error)
					: errorFallback}
			</>
		)
	}
	if (isStandalone) {
		// Wait for the effect to seed placeholder host state; otherwise hooks
		// in `children` would throw.
		if (host.status !== "initialized") {
			return <>{fallback}</>
		}
		return (
			<>
				<div role="status" className="custom-blocks-standalone-banner">
					Host not detected — running in standalone preview. Try `ntn workers
					customblocks dev` to run the block in a local development environment.
				</div>
				{children}
			</>
		)
	}
	if (!init.isLoaded) {
		return <>{fallback}</>
	}
	return <>{children}</>
}

/**
 * Host-agnostic fallback for custom block initialization errors.
 *
 * The production Notion host and the dev shell both cover the iframe and render their own error
 * surfaces. But a generic host may not, so we show this component inside the iframe to provide a
 * decent fallback experience.
 */
function DefaultInitErrorFallback({
	error,
}: {
	error: CustomBlockInitializationError
}) {
	useEffect(() => {
		console.warn(
			`[custom-blocks-sdk] Custom block init failed: ${error.message}`,
		)
	}, [error])

	const errorDetails = JSON.stringify(
		{
			code: error.code,
			message: error.message,
			isRetryable: error.isRetryable,
		},
		null,
		2,
	)

	return (
		<div role="alert" className="custom-blocks-default-init-error">
			<div className="custom-blocks-default-init-error__card">
				<h2 className="custom-blocks-default-init-error__title">
					Custom block failed to initialize
				</h2>
				<p className="custom-blocks-default-init-error__body">
					The custom block loaded, but its setup handshake did not finish. Try
					again. If this keeps happening, check the browser console for more
					details.
				</p>
				<details className="custom-blocks-default-init-error__details">
					<summary>Developer details</summary>
					<pre className="custom-blocks-default-init-error__pre">
						{errorDetails}
					</pre>
				</details>
			</div>
		</div>
	)
}
